// ===== data/makes/skoda.js =====
// Škoda: моделі → покоління → варіанти (двигун + роки + коробки).
//
// Формат варіанта:
//   engine  — ключ з data/engines.js
//   label   — як показувати у списку
//   years   — [з якого, по який]; null = випускається досі
